// lib
namespace Lib;

// Plain model type: no MessagePack reference, no attributes.
public class MyType
{
    public int A { get; set; }
    public string? B { get; set; }
}
// app
using MessagePack;
using MessagePack.Formatters;
using Lib;
namespace App;

// New: the generator collects this declaration as a GeneratedFormatterRequest
// (formatter MyTypeFormatter, data type Lib.MyType) and emits Serialize/Deserialize
// into the other half of the partial class. Build succeeds.
// Old: no GeneratedFormatterRequest, no [GeneratedMessagePackFormatter], nothing generated.
// Build fails: CS0246 on the attribute, CS0535 for the two unimplemented interface members.
[GeneratedMessagePackFormatter]
public sealed partial class MyTypeFormatter : IMessagePackFormatter<MyType>;

public static class Use
{
    // Binds only if the generated half of MyTypeFormatter exists.
    public static byte[] Pack(MyType value, MessagePackSerializerOptions options)
    {
        var buffer = new System.Buffers.ArrayBufferWriter<byte>();
        var writer = new MessagePackWriter(buffer);
        new MyTypeFormatter().Serialize(ref writer, value, options);
        writer.Flush();
        return buffer.WrittenSpan.ToArray();
    }

    public static MyType Unpack(byte[] bytes, MessagePackSerializerOptions options)
    {
        var reader = new MessagePackReader(bytes);
        return new MyTypeFormatter().Deserialize(ref reader, options);
    }
}
